module TageTable(
  input         clock,
                reset,
                io_f1_req_valid,
  input  [39:0] io_f1_req_pc,
  input  [63:0] io_f1_req_ghist,
  output        io_f2_resp_0_valid,
  output [2:0]  io_f2_resp_0_bits_ctr,
