  output [2:0]  io_f2_resp_3_bits_ctr,
  output [1:0]  io_f2_resp_3_bits_u,
  input         io_update_mask_0,
                io_update_mask_1,
                io_update_mask_2,
                io_update_mask_3,
                io_update_taken_0,
                io_update_taken_1,
