                io_update_old_ctr_2,
                io_update_old_ctr_3,
  input  [39:0] io_update_pc,
  input  [63:0] io_update_hist,
  input         io_update_u_mask_0,
                io_update_u_mask_1,
                io_update_u_mask_2,
                io_update_u_mask_3,
  input  [1:0]  io_update_u_0,
                io_update_u_1,
                io_update_u_2,
                io_update_u_3
);

  wire [2:0]  update_wdata_3_ctr;
  wire [2:0]  update_wdata_2_ctr;
  wire [2:0]  update_wdata_1_ctr;
  wire [2:0]  update_wdata_0_ctr;
  wire        wdata_1_7;
  wire        wdata_1_6;
  wire        wdata_1_5;
  wire        wdata_1_4;
  wire        wdata_1_3;
  wire        wdata_1_2;
  wire        wdata_1_1;
  wire        wdata_1_0;
  wire [10:0] wdata_3;
  wire [10:0] wdata_2;
  wire [10:0] wdata_1;
  wire [10:0] wdata_0;
  wire        s2_req_rtage_3_valid;
  wire [6:0]  s2_req_rtage_3_tag;
  wire        s2_req_rtage_2_valid;
  wire [6:0]  s2_req_rtage_2_tag;
  wire        s2_req_rtage_1_valid;
  wire [6:0]  s2_req_rtage_1_tag;
  wire        s2_req_rtage_0_valid;
  wire [6:0]  s2_req_rtage_0_tag;
  wire [43:0] _tage_table_2_ext_R0_data;
  wire [7:0]  _tage_u_2_ext_R0_data;
  reg         doing_reset;
  reg  [6:0]  reset_idx;
  wire [6:0]  s1_hashed_idx =
    {io_f1_req_pc[9:5], io_f1_req_pc[4:3] ^ io_f1_req_ghist[1:0]};
  reg  [6:0]  s2_tag;
  reg  [18:0] clear_u_ctr;
  wire        doing_clear_u = clear_u_ctr[10:0] == 11'h0;
  wire [1:0]  _GEN = io_update_pc[4:3] ^ io_update_hist[1:0];
  wire [6:0]  update_idx = {io_update_pc[9:5], _GEN};
  wire [1:0]  _GEN_0 = io_update_pc[11:10] ^ io_update_hist[1:0];
  wire [6:0]  update_tag = {io_update_pc[16:12], _GEN_0};
  wire        _wen_T = io_update_mask_0 | io_update_mask_1;
  assign s2_req_rtage_0_tag = _tage_table_2_ext_R0_data[9:3];
  assign s2_req_rtage_0_valid = _tage_table_2_ext_R0_data[10];
  assign s2_req_rtage_1_tag = _tage_table_2_ext_R0_data[20:14];
  assign s2_req_rtage_1_valid = _tage_table_2_ext_R0_data[21];
  assign s2_req_rtage_2_tag = _tage_table_2_ext_R0_data[31:25];
  assign s2_req_rtage_2_valid = _tage_table_2_ext_R0_data[32];
  assign s2_req_rtage_3_tag = _tage_table_2_ext_R0_data[42:36];
  assign s2_req_rtage_3_valid = _tage_table_2_ext_R0_data[43];
  assign wdata_0 =
    doing_reset ? 11'h0 : {1'h1, io_update_pc[16:12], _GEN_0, update_wdata_0_ctr};
  assign wdata_1 =
    doing_reset ? 11'h0 : {1'h1, io_update_pc[16:12], _GEN_0, update_wdata_1_ctr};
  assign wdata_2 =
    doing_reset ? 11'h0 : {1'h1, io_update_pc[16:12], _GEN_0, update_wdata_2_ctr};
  assign wdata_3 =
    doing_reset ? 11'h0 : {1'h1, io_update_pc[16:12], _GEN_0, update_wdata_3_ctr};
  wire        _wdata_T_4 = doing_reset | doing_clear_u;
  assign wdata_1_0 = ~_wdata_T_4 & io_update_u_0[0];
  assign wdata_1_1 = ~_wdata_T_4 & io_update_u_0[1];
  assign wdata_1_2 = ~_wdata_T_4 & io_update_u_1[0];
  assign wdata_1_3 = ~_wdata_T_4 & io_update_u_1[1];
  assign wdata_1_4 = ~_wdata_T_4 & io_update_u_2[0];
  assign wdata_1_5 = ~_wdata_T_4 & io_update_u_2[1];
  assign wdata_1_6 = ~_wdata_T_4 & io_update_u_3[0];
  assign wdata_1_7 = ~_wdata_T_4 & io_update_u_3[1];
  reg  [6:0]  wrbypass_tags_0;
  reg  [6:0]  wrbypass_tags_1;
  reg  [6:0]  wrbypass_idxs_0;
  reg  [6:0]  wrbypass_idxs_1;
  reg  [2:0]  wrbypass_0_0;
  reg  [2:0]  wrbypass_0_1;
  reg  [2:0]  wrbypass_0_2;
  reg  [2:0]  wrbypass_0_3;
  reg  [2:0]  wrbypass_1_0;
  reg  [2:0]  wrbypass_1_1;
  reg  [2:0]  wrbypass_1_2;
  reg  [2:0]  wrbypass_1_3;
  reg         wrbypass_enq_idx;
  wire        wrbypass_hits_0 =
    ~doing_reset & wrbypass_tags_0 == update_tag & wrbypass_idxs_0 == update_idx;
  wire        wrbypass_hit =
    wrbypass_hits_0 | ~doing_reset & wrbypass_tags_1 == update_tag
    & wrbypass_idxs_1 == update_idx;
  wire [2:0]  _GEN_1 = wrbypass_hits_0 ? wrbypass_0_0 : wrbypass_1_0;
  wire [2:0]  _GEN_2 = wrbypass_hits_0 ? wrbypass_0_1 : wrbypass_1_1;
  wire [2:0]  _GEN_3 = wrbypass_hits_0 ? wrbypass_0_2 : wrbypass_1_2;
  wire [2:0]  _GEN_4 = wrbypass_hits_0 ? wrbypass_0_3 : wrbypass_1_3;
  assign update_wdata_0_ctr =
    io_update_alloc_0
      ? (io_update_taken_0 ? 3'h4 : 3'h3)
      : wrbypass_hit
          ? (io_update_taken_0
               ? ((&_GEN_1) ? 3'h7 : _GEN_1 + 3'h1)
               : _GEN_1 == 3'h0 ? 3'h0 : _GEN_1 - 3'h1)
          : io_update_taken_0
              ? ((&io_update_old_ctr_0) ? 3'h7 : io_update_old_ctr_0 + 3'h1)
              : io_update_old_ctr_0 == 3'h0 ? 3'h0 : io_update_old_ctr_0 - 3'h1;
  assign update_wdata_1_ctr =
    io_update_alloc_1
      ? (io_update_taken_1 ? 3'h4 : 3'h3)
      : wrbypass_hit
          ? (io_update_taken_1
               ? ((&_GEN_2) ? 3'h7 : _GEN_2 + 3'h1)
               : _GEN_2 == 3'h0 ? 3'h0 : _GEN_2 - 3'h1)
          : io_update_taken_1
              ? ((&io_update_old_ctr_1) ? 3'h7 : io_update_old_ctr_1 + 3'h1)
              : io_update_old_ctr_1 == 3'h0 ? 3'h0 : io_update_old_ctr_1 - 3'h1;
  assign update_wdata_2_ctr =
    io_update_alloc_2
      ? (io_update_taken_2 ? 3'h4 : 3'h3)
      : wrbypass_hit
          ? (io_update_taken_2
               ? ((&_GEN_3) ? 3'h7 : _GEN_3 + 3'h1)
               : _GEN_3 == 3'h0 ? 3'h0 : _GEN_3 - 3'h1)
          : io_update_taken_2
              ? ((&io_update_old_ctr_2) ? 3'h7 : io_update_old_ctr_2 + 3'h1)
              : io_update_old_ctr_2 == 3'h0 ? 3'h0 : io_update_old_ctr_2 - 3'h1;
  assign update_wdata_3_ctr =
    io_update_alloc_3
      ? (io_update_taken_3 ? 3'h4 : 3'h3)
      : wrbypass_hit
          ? (io_update_taken_3
               ? ((&_GEN_4) ? 3'h7 : _GEN_4 + 3'h1)
               : _GEN_4 == 3'h0 ? 3'h0 : _GEN_4 - 3'h1)
          : io_update_taken_3
              ? ((&io_update_old_ctr_3) ? 3'h7 : io_update_old_ctr_3 + 3'h1)
              : io_update_old_ctr_3 == 3'h0 ? 3'h0 : io_update_old_ctr_3 - 3'h1;
  wire        _GEN_5 = _wen_T | io_update_mask_2 | io_update_mask_3;
  wire        _GEN_6 = ~_GEN_5 | wrbypass_hit | wrbypass_enq_idx;
  wire        _GEN_7 = ~_GEN_5 | wrbypass_hit | ~wrbypass_enq_idx;
  always @(posedge clock) begin
    if (reset) begin
      doing_reset <= 1'h1;
      reset_idx <= 7'h0;
      clear_u_ctr <= 19'h0;
      wrbypass_enq_idx <= 1'h0;
    end
    else begin
      doing_reset <= reset_idx != 7'h7F & doing_reset;
      reset_idx <= reset_idx + {6'h0, doing_reset};
      clear_u_ctr <= doing_reset ? 19'h1 : clear_u_ctr + 19'h1;
      if (~_GEN_5 | wrbypass_hit) begin
      end
      else
        wrbypass_enq_idx <= wrbypass_enq_idx - 1'h1;
    end
    s2_tag <= {io_f1_req_pc[16:12], io_f1_req_pc[11:10] ^ io_f1_req_ghist[1:0]};
    if (_GEN_6) begin
    end
    else
      wrbypass_tags_0 <= update_tag;
    if (_GEN_7) begin
    end
    else
      wrbypass_tags_1 <= update_tag;
    if (_GEN_6) begin
    end
    else
      wrbypass_idxs_0 <= update_idx;
    if (_GEN_7) begin
    end
    else
      wrbypass_idxs_1 <= update_idx;
    if (_GEN_5) begin
      if (wrbypass_hit) begin
        if (wrbypass_hits_0) begin
          wrbypass_0_0 <= update_wdata_0_ctr;
          wrbypass_0_1 <= update_wdata_1_ctr;
          wrbypass_0_2 <= update_wdata_2_ctr;
          wrbypass_0_3 <= update_wdata_3_ctr;
        end
