      Memory[RW0_addr][32'h6 +: 2] <= RW0_wdata[7:6];
  end // always @(posedge)
  assign RW0_rdata = _RW0_ren_d0 & ~_RW0_rmode_d0 ? Memory[_RW0_raddr_d0] : 8'bx;
endmodule

