module PMAChecker(
  input  [39:0] io_paddr,
  output        io_resp_cacheable,
                io_resp_r,
                io_resp_w,
                io_resp_pp,
                io_resp_al,
                io_resp_aa,
                io_resp_x,
                io_resp_eff
);

  wire [9:0] _GEN = io_paddr[25:16] ^ 10'h200;
  wire [3:0] _GEN_0 = io_paddr[31:28] ^ 4'h8;
  wire       legal_address =
    {io_paddr[39:14], ~(io_paddr[13:12])} == 28'h0 | {io_paddr[39:26], _GEN} == 24'h0
    | {io_paddr[39:28], ~(io_paddr[27:26])} == 14'h0 | {io_paddr[39:32], _GEN_0} == 12'h0;
  assign io_resp_cacheable = legal_address & ~(_GEN_0[3]);
  assign io_resp_r = legal_address;
  assign io_resp_w = legal_address;
  assign io_resp_pp = legal_address;
  assign io_resp_al = legal_address & ~(io_paddr[31]);
  assign io_resp_aa = legal_address & ~(io_paddr[31]);
  assign io_resp_x =
    legal_address & ({io_paddr[31], io_paddr[27], io_paddr[25]} == 3'h0 | ~(_GEN_0[3]));
  assign io_resp_eff =
    legal_address
    & ({io_paddr[31], io_paddr[27], _GEN[9]} == 3'h0
       | {io_paddr[31], ~(io_paddr[27])} == 2'h0);
endmodule

