  reg [11:0] uops_0_bits_uop_br_mask;
  reg [5:0]  uops_0_bits_uop_rob_idx;
  reg [6:0]  uops_0_bits_uop_pdst;
  reg [1:0]  uops_0_bits_uop_dst_rtype;
  reg        uops_1_valid;
  reg [11:0] uops_1_bits_uop_br_mask;
  reg [5:0]  uops_1_bits_uop_rob_idx;
  reg [6:0]  uops_1_bits_uop_pdst;
