                           : remainder[38] ? 2'h2 : {1'h0, remainder[37]})
                      : remainder[35]
                          ? 2'h3
                          : remainder[34] ? 2'h2 : {1'h0, remainder[33]}}}}
       : {|(remainder[31:16]),
          (|(remainder[31:16]))
            ? {|(remainder[31:24]),
               (|(remainder[31:24]))
                 ? {|(remainder[31:28]),
                    (|(remainder[31:28]))
                      ? (remainder[31]
                           ? 2'h3
                           : remainder[30] ? 2'h2 : {1'h0, remainder[29]})
                      : remainder[27]
                          ? 2'h3
                          : remainder[26] ? 2'h2 : {1'h0, remainder[25]}}
                 : {|(remainder[23:20]),
                    (|(remainder[23:20]))
                      ? (remainder[23]
                           ? 2'h3
                           : remainder[22] ? 2'h2 : {1'h0, remainder[21]})
                      : remainder[19]
                          ? 2'h3
                          : remainder[18] ? 2'h2 : {1'h0, remainder[17]}}}
            : {|(remainder[15:8]),
               (|(remainder[15:8]))
                 ? {|(remainder[15:12]),
                    (|(remainder[15:12]))
                      ? (remainder[15]
                           ? 2'h3
                           : remainder[14] ? 2'h2 : {1'h0, remainder[13]})
                      : remainder[11]
                          ? 2'h3
                          : remainder[10] ? 2'h2 : {1'h0, remainder[9]}}
                 : {|(remainder[7:4]),
                    (|(remainder[7:4]))
                      ? (remainder[7] ? 2'h3 : remainder[6] ? 2'h2 : {1'h0, remainder[5]})
                      : remainder[3]
                          ? 2'h3
                          : remainder[2] ? 2'h2 : {1'h0, remainder[1]}}}}}
    - {|(divisor[63:32]),
       (|(divisor[63:32]))
         ? {|(divisor[63:48]),
            (|(divisor[63:48]))
              ? {|(divisor[63:56]),
                 (|(divisor[63:56]))
                   ? {|(divisor[63:60]),
                      (|(divisor[63:60]))
                        ? (divisor[63] ? 2'h3 : divisor[62] ? 2'h2 : {1'h0, divisor[61]})
                        : divisor[59] ? 2'h3 : divisor[58] ? 2'h2 : {1'h0, divisor[57]}}
                   : {|(divisor[55:52]),
                      (|(divisor[55:52]))
                        ? (divisor[55] ? 2'h3 : divisor[54] ? 2'h2 : {1'h0, divisor[53]})
                        : divisor[51] ? 2'h3 : divisor[50] ? 2'h2 : {1'h0, divisor[49]}}}
              : {|(divisor[47:40]),
                 (|(divisor[47:40]))
                   ? {|(divisor[47:44]),
                      (|(divisor[47:44]))
                        ? (divisor[47] ? 2'h3 : divisor[46] ? 2'h2 : {1'h0, divisor[45]})
                        : divisor[43] ? 2'h3 : divisor[42] ? 2'h2 : {1'h0, divisor[41]}}
                   : {|(divisor[39:36]),
                      (|(divisor[39:36]))
                        ? (divisor[39] ? 2'h3 : divisor[38] ? 2'h2 : {1'h0, divisor[37]})
                        : divisor[35] ? 2'h3 : divisor[34] ? 2'h2 : {1'h0, divisor[33]}}}}
         : {|(divisor[31:16]),
            (|(divisor[31:16]))
              ? {|(divisor[31:24]),
                 (|(divisor[31:24]))
                   ? {|(divisor[31:28]),
                      (|(divisor[31:28]))
                        ? (divisor[31] ? 2'h3 : divisor[30] ? 2'h2 : {1'h0, divisor[29]})
                        : divisor[27] ? 2'h3 : divisor[26] ? 2'h2 : {1'h0, divisor[25]}}
                   : {|(divisor[23:20]),
                      (|(divisor[23:20]))
                        ? (divisor[23] ? 2'h3 : divisor[22] ? 2'h2 : {1'h0, divisor[21]})
                        : divisor[19] ? 2'h3 : divisor[18] ? 2'h2 : {1'h0, divisor[17]}}}
              : {|(divisor[15:8]),
                 (|(divisor[15:8]))
                   ? {|(divisor[15:12]),
                      (|(divisor[15:12]))
                        ? (divisor[15] ? 2'h3 : divisor[14] ? 2'h2 : {1'h0, divisor[13]})
                        : divisor[11] ? 2'h3 : divisor[10] ? 2'h2 : {1'h0, divisor[9]}}
                   : {|(divisor[7:4]),
                      (|(divisor[7:4]))
                        ? (divisor[7] ? 2'h3 : divisor[6] ? 2'h2 : {1'h0, divisor[5]})
                        : divisor[3] ? 2'h3 : divisor[2] ? 2'h2 : {1'h0, divisor[1]}}}}};
  wire [65:0]  _prod_T_4 =
    {{65{remainder[64]}}, remainder[0]} * {divisor[64], divisor}
    + {remainder[129], remainder[129:65]};
  wire [2:0]   decoded_invInputs = ~(io_req_bits_fn[2:0]);
  wire [1:0]   _decoded_andMatrixOutputs_T = {decoded_invInputs[1], decoded_invInputs[2]};
  wire [1:0]   _decoded_orMatrixOutputs_T_4 =
    {&{io_req_bits_fn[0], decoded_invInputs[2]}, io_req_bits_fn[1]};
  wire         lhs_sign =
    (|{decoded_invInputs[0], &_decoded_andMatrixOutputs_T})
    & (io_req_bits_dw ? io_req_bits_in1[63] : io_req_bits_in1[31]);
  wire         rhs_sign =
    (|{&_decoded_andMatrixOutputs_T, &{decoded_invInputs[0], io_req_bits_fn[2]}})
    & (io_req_bits_dw ? io_req_bits_in2[63] : io_req_bits_in2[31]);
  wire [64:0]  _subtractor_T_1 = remainder[128:64] - divisor;
  wire         _GEN = state == 3'h1;
  wire         _GEN_0 = state == 3'h5;
  wire         _GEN_1 = state == 3'h2;
  wire         _GEN_2 = _GEN_1 & count == 7'h3F;
  wire         _GEN_3 = state == 3'h3;
  wire         _GEN_4 = count == 7'h40;
  wire         _eOut_T_9 = count == 7'h0;
  wire         divby0 = _eOut_T_9 & ~(_subtractor_T_1[64]);
  wire         _GEN_5 = io_req_ready_0 & io_req_valid;
  wire         eOut_1 = _eOut_T_9 & ~divby0 & _eOutPos_T != 6'h3F;
  always @(posedge clock) begin
    if (reset)
      state <= 3'h0;
    else if (_GEN_5)
      state <= decoded_invInputs[2] ? 3'h2 : {1'h0, ~(lhs_sign | rhs_sign), 1'h1};
    else if (io_resp_ready & io_resp_valid_0 | io_kill)
      state <= 3'h0;
    else if (_GEN_3 & _GEN_4)
      state <= {1'h1, ~neg_out, 1'h1};
    else if (_GEN_2)
      state <= 3'h6;
    else if (_GEN_0)
      state <= 3'h7;
    else if (_GEN)
      state <= 3'h3;
    if (_GEN_5) begin
      req_dw <= io_req_bits_dw;
      count <= {1'h0, decoded_invInputs[2] & ~io_req_bits_dw, 5'h0};
      isHi <= |_decoded_orMatrixOutputs_T_4;
      divisor <=
        {rhs_sign,
         io_req_bits_dw ? io_req_bits_in2[63:32] : {32{rhs_sign}},
         io_req_bits_in2[31:0]};
      remainder <=
        {66'h0,
         io_req_bits_dw ? io_req_bits_in1[63:32] : {32{lhs_sign}},
         io_req_bits_in1[31:0]};
    end
    else begin
      if (_GEN_3) begin
        count <= eOut_1 ? {1'h0, ~_eOutPos_T} : count + 7'h1;
        remainder <=
          eOut_1
            ? {3'h0, {63'h0, remainder[63:0]} << ~_eOutPos_T}
            : {1'h0,
               _subtractor_T_1[64] ? remainder[127:64] : _subtractor_T_1[63:0],
               remainder[63:0],
               ~(_subtractor_T_1[64])};
      end
      else if (_GEN_1) begin
        count <= count + 7'h1;
        remainder <=
          {_prod_T_4[65:1], count == 7'h3E & neg_out, _prod_T_4[0], remainder[63:1]};
      end
      else if (_GEN_0 | _GEN & remainder[63])
        remainder <= {66'h0, 64'h0 - result};
      if (_GEN & divisor[63])
        divisor <= _subtractor_T_1;
    end
    neg_out <=
      _GEN_5
        ? ((|_decoded_orMatrixOutputs_T_4) ? lhs_sign : lhs_sign != rhs_sign)
        : ~(_GEN_3 & divby0 & ~isHi) & neg_out;
    resHi <= ~_GEN_5 & (_GEN_3 & _GEN_4 | _GEN_2 ? isHi : ~_GEN_0 & resHi);
  end // always @(posedge)
  assign io_req_ready = io_req_ready_0;
  assign io_resp_valid = io_resp_valid_0;
  assign io_resp_bits_data = {req_dw ? result[63:32] : {32{loOut[31]}}, loOut};
endmodule

module DivUnit(
  input         clock,
                reset,
                io_kill,
  output        io_req_ready,
  input         io_req_valid,
  input  [11:0] io_req_bits_uop_br_mask,
  input  [5:0]  io_req_bits_uop_rob_idx,
  input  [6:0]  io_req_bits_uop_pdst,
  input  [1:0]  io_req_bits_uop_dst_rtype,
  input         io_req_bits_uop_fcn_dw,
  input  [4:0]  io_req_bits_uop_fcn_op,
  input  [63:0] io_req_bits_rs1_data,
                io_req_bits_rs2_data,
  input         io_resp_ready,
  output        io_resp_valid,
  output [11:0] io_resp_bits_uop_br_mask,
  output [5:0]  io_resp_bits_uop_rob_idx,
  output [6:0]  io_resp_bits_uop_pdst,
  output [1:0]  io_resp_bits_uop_dst_rtype,
  output [63:0] io_resp_bits_data,
  input  [11:0] io_brupdate_b1_resolve_mask,
                io_brupdate_b1_mispredict_mask
);

  wire        _div_io_req_ready;
  wire        _div_io_resp_valid;
  reg         req_valid;
  reg  [11:0] req_bits_br_mask;
  reg  [5:0]  req_bits_rob_idx;
  reg  [6:0]  req_bits_pdst;
  reg  [1:0]  req_bits_dst_rtype;
  wire        io_req_ready_0 = _div_io_req_ready & ~req_valid;
  wire        io_resp_valid_0 = _div_io_resp_valid & req_valid;
  wire        _GEN = io_req_ready_0 & io_req_valid;
  always @(posedge clock) begin
    req_valid <=
      ~(io_resp_ready & io_resp_valid_0 | reset)
      & (_GEN
           ? ~((|(io_brupdate_b1_mispredict_mask & io_req_bits_uop_br_mask)) | io_kill)
           : ~((|(io_brupdate_b1_mispredict_mask & req_bits_br_mask)) | io_kill)
             & req_valid);
    req_bits_br_mask <=
      _GEN
        ? io_req_bits_uop_br_mask & ~io_brupdate_b1_resolve_mask
        : req_bits_br_mask & ~io_brupdate_b1_resolve_mask;
    if (_GEN) begin
      req_bits_rob_idx <= io_req_bits_uop_rob_idx;
      req_bits_pdst <= io_req_bits_uop_pdst;
      req_bits_dst_rtype <= io_req_bits_uop_dst_rtype;
    end
  end // always @(posedge)
  MulDiv div (
    .clock             (clock),
    .reset             (reset),
    .io_req_ready      (_div_io_req_ready),
    .io_req_valid
      (io_req_valid
       & ~((|(io_brupdate_b1_mispredict_mask & io_req_bits_uop_br_mask)) | io_kill)),
    .io_req_bits_fn    (io_req_bits_uop_fcn_op),
    .io_req_bits_dw    (io_req_bits_uop_fcn_dw),
    .io_req_bits_in1   (io_req_bits_rs1_data),
    .io_req_bits_in2   (io_req_bits_rs2_data),
    .io_kill
      (req_valid & ((|(io_brupdate_b1_mispredict_mask & req_bits_br_mask)) | io_kill)),
    .io_resp_ready     (io_resp_ready),
    .io_resp_valid     (_div_io_resp_valid),
    .io_resp_bits_data (io_resp_bits_data)
  );
  assign io_req_ready = io_req_ready_0;
  assign io_resp_valid = io_resp_valid_0;
  assign io_resp_bits_uop_br_mask = req_bits_br_mask;
  assign io_resp_bits_uop_rob_idx = req_bits_rob_idx;
  assign io_resp_bits_uop_pdst = req_bits_pdst;
  assign io_resp_bits_uop_dst_rtype = req_bits_dst_rtype;
endmodule

