    {|(io_c[51:48]),
     |(io_c[47:44]),
     |(io_c[43:40]),
     |(io_c[39:36]),
     |(io_c[35:32]),
     |(io_c[31:28]),
     |(io_c[27:24]),
     |(io_c[23:20]),
     |(io_c[19:16]),
     |(io_c[15:12]),
     |(io_c[11:8]),
     |(io_c[7:4]),
