        _GEN_0
          ? (_GEN
               ? {fsgnjMux_data[64:33], _narrower_io_out}
               : {fsgnjMux_data[64:33],
                  fsgnjMux_data[64],
                  fsgnjMux_data[63:61] == 3'h0 | fsgnjMux_data[63:61] > 3'h5
                    ? {fsgnjMux_data[63:61], _mux_data_expOut_commonCase_T[5:0]}
                    : _mux_data_expOut_commonCase_T,
                  fsgnjMux_data[51:29]})
          : fsgnjMux_data;
      io_out_pipe_b_exc <=
        _GEN & _GEN_0
          ? _narrower_io_exceptionFlags
          : _GEN
              ? {(&(in_pipe_b_in1[63:61])) & ~(in_pipe_b_in1[51]), 4'h0}
              : in_pipe_b_wflags
                  ? {(&(in_pipe_b_in1[63:61])) & ~(in_pipe_b_in1[51])
