module DivSqrtRawFN_small(
  input         clock,
                reset,
  output        io_inReady,
  input         io_inValid,
                io_sqrtOp,
                io_a_isNaN,
                io_a_isInf,
                io_a_isZero,
                io_a_sign,
  input  [9:0]  io_a_sExp,
  input  [24:0] io_a_sig,
  input         io_b_isNaN,
                io_b_isInf,
                io_b_isZero,
                io_b_sign,
  input  [9:0]  io_b_sExp,
  input  [24:0] io_b_sig,
  input  [2:0]  io_roundingMode,
  output        io_rawOutValid_div,
                io_rawOutValid_sqrt,
  output [2:0]  io_roundingModeOut,
  output        io_invalidExc,
                io_infiniteExc,
                io_rawOut_isNaN,
                io_rawOut_isInf,
                io_rawOut_isZero,
                io_rawOut_sign,
  output [9:0]  io_rawOut_sExp,
  output [26:0] io_rawOut_sig
);

  reg  [4:0]  cycleNum;
  reg         inReady;
  reg         rawOutValid;
  reg         sqrtOp_Z;
  reg         majorExc_Z;
  reg         isNaN_Z;
  reg         isInf_Z;
  reg         isZero_Z;
  reg         sign_Z;
  reg  [9:0]  sExp_Z;
  reg  [23:0] fractB_Z;
  reg  [2:0]  roundingMode_Z;
  reg  [25:0] rem_Z;
  reg         notZeroRem_Z;
  reg  [25:0] sigX_Z;
  wire        specialCaseA_S = io_a_isNaN | io_a_isInf | io_a_isZero;
  wire        normalCase_S =
    io_sqrtOp
      ? ~specialCaseA_S & ~io_a_sign
      : ~specialCaseA_S & ~(io_b_isNaN | io_b_isInf | io_b_isZero);
  wire        skipCycle2 = cycleNum == 5'h3 & sigX_Z[25];
  wire        notSigNaNIn_invalidExc_S_div =
    io_a_isZero & io_b_isZero | io_a_isInf & io_b_isInf;
  wire        notSigNaNIn_invalidExc_S_sqrt = ~io_a_isNaN & ~io_a_isZero & io_a_sign;
  wire [10:0] sExpQuot_S_div =
    {io_a_sExp[9], io_a_sExp} + {{3{io_b_sExp[8]}}, ~(io_b_sExp[7:0])};
  wire [23:0] _fractB_Z_T_4 = inReady & ~io_sqrtOp ? {io_b_sig[22:0], 1'h0} : 24'h0;
  wire        _fractB_Z_T_10 = inReady & io_sqrtOp;
  wire [31:0] _bitMask_T = 32'h1 << cycleNum;
  wire        oddSqrt_S = io_sqrtOp & io_a_sExp[0];
  wire        entering = inReady & io_inValid;
  wire        _sigX_Z_T_7 = inReady & oddSqrt_S;
  wire [26:0] rem =
    {1'h0, inReady & ~oddSqrt_S ? {io_a_sig, 1'h0} : 26'h0}
    | (_sigX_Z_T_7 ? {io_a_sig[23:22] - 2'h1, io_a_sig[21:0], 3'h0} : 27'h0)
    | (inReady ? 27'h0 : {rem_Z, 1'h0});
  wire [25:0] _trialTerm_T_3 = inReady & ~io_sqrtOp ? {io_b_sig, 1'h0} : 26'h0;
  wire [25:0] _trialTerm_T_9 =
    {_trialTerm_T_3[25],
     _trialTerm_T_3[24:0] | {inReady & io_sqrtOp & ~(io_a_sExp[0]), 24'h0}}
    | (_sigX_Z_T_7 ? 26'h2800000 : 26'h0);
  wire [28:0] trialRem =
    {2'h0, rem}
    - {2'h0,
       {1'h0,
        _trialTerm_T_9[25],
        _trialTerm_T_9[24] | ~inReady & ~sqrtOp_Z,
        _trialTerm_T_9[23:0] | (inReady ? 24'h0 : fractB_Z)}
         | (~inReady & sqrtOp_Z ? {sigX_Z, 1'h0} : 27'h0)};
  wire        newBit = $signed(trialRem) > -29'sh1;
  wire        _GEN = entering | ~inReady;
  wire [4:0]  _cycleNum_T_15 =
    {4'h0, entering & ~normalCase_S}
    | (entering & normalCase_S ? (io_sqrtOp ? {4'hC, ~(io_a_sExp[0])} : 5'h1A) : 5'h0)
    | (entering | skipCycle2 ? 5'h0 : cycleNum - 5'h1);
  wire [25:0] _sigX_Z_T_3 = inReady & ~io_sqrtOp ? {newBit, 25'h0} : 26'h0;
  wire [24:0] _GEN_0 = _sigX_Z_T_3[24:0] | {inReady & io_sqrtOp, 24'h0};
  always @(posedge clock) begin
    if (reset) begin
      cycleNum <= 5'h0;
      inReady <= 1'h1;
      rawOutValid <= 1'h0;
    end
    else if ((|cycleNum) | entering) begin
      cycleNum <= {_cycleNum_T_15[4:1], _cycleNum_T_15[0] | skipCycle2};
      inReady <=
        entering & ~normalCase_S | ~entering & ~skipCycle2 & cycleNum - 5'h1 < 5'h2
        | skipCycle2;
      rawOutValid <=
        entering & ~normalCase_S | ~entering & ~skipCycle2 & cycleNum - 5'h1 == 5'h1
        | skipCycle2;
    end
    if (entering) begin
      sqrtOp_Z <= io_sqrtOp;
      majorExc_Z <=
        io_sqrtOp
          ? io_a_isNaN & ~(io_a_sig[22]) | notSigNaNIn_invalidExc_S_sqrt
          : io_a_isNaN & ~(io_a_sig[22]) | io_b_isNaN & ~(io_b_sig[22])
            | notSigNaNIn_invalidExc_S_div | ~io_a_isNaN & ~io_a_isInf & io_b_isZero;
      isNaN_Z <=
        io_sqrtOp
          ? io_a_isNaN | notSigNaNIn_invalidExc_S_sqrt
          : io_a_isNaN | io_b_isNaN | notSigNaNIn_invalidExc_S_div;
      isInf_Z <= ~io_sqrtOp & io_b_isZero | io_a_isInf;
      isZero_Z <= ~io_sqrtOp & io_b_isInf | io_a_isZero;
      sign_Z <= io_a_sign ^ ~io_sqrtOp & io_b_sign;
      sExp_Z <=
        io_sqrtOp
          ? {io_a_sExp[9], io_a_sExp[9:1]} + 10'h80
          : {$signed(sExpQuot_S_div) > 11'sh1BF ? 4'h6 : sExpQuot_S_div[9:6],
             sExpQuot_S_div[5:0]};
      roundingMode_Z <= io_roundingMode;
    end
    if (entering | ~inReady & sqrtOp_Z)
      fractB_Z <=
        {_fractB_Z_T_4[23] | _fractB_Z_T_10 & ~(io_a_sExp[0]),
         _fractB_Z_T_4[22:0] | {_fractB_Z_T_10 & io_a_sExp[0], 22'h0}
           | (inReady ? 23'h0 : fractB_Z[23:1])};
    if (_GEN) begin
      rem_Z <= newBit ? trialRem[25:0] : rem[25:0];
      sigX_Z <=
        {_sigX_Z_T_3[25],
         _GEN_0[24],
         _GEN_0[23:0] | (_sigX_Z_T_7 ? {newBit, 23'h0} : 24'h0)}
        | (inReady ? 26'h0 : sigX_Z) | (~inReady & newBit ? _bitMask_T[27:2] : 26'h0);
    end
    if (_GEN & (inReady | newBit))
      notZeroRem_Z <= |trialRem;
  end // always @(posedge)
  assign io_inReady = inReady;
  assign io_rawOutValid_div = rawOutValid & ~sqrtOp_Z;
  assign io_rawOutValid_sqrt = rawOutValid & sqrtOp_Z;
  assign io_roundingModeOut = roundingMode_Z;
  assign io_invalidExc = majorExc_Z & isNaN_Z;
  assign io_infiniteExc = majorExc_Z & ~isNaN_Z;
  assign io_rawOut_isNaN = isNaN_Z;
  assign io_rawOut_isInf = isInf_Z;
  assign io_rawOut_isZero = isZero_Z;
  assign io_rawOut_sign = sign_Z;
  assign io_rawOut_sExp = sExp_Z;
  assign io_rawOut_sig = {sigX_Z, notZeroRem_Z};
endmodule

