// VCS coverage exclude_file
module regfile_64x65(
  input  [5:0]  R0_addr,
  input         R0_en,
                R0_clk,
  output [64:0] R0_data,
  input  [5:0]  R1_addr,
  input         R1_en,
                R1_clk,
  output [64:0] R1_data,
  input  [5:0]  R2_addr,
  input         R2_en,
                R2_clk,
  output [64:0] R2_data,
  input  [5:0]  W0_addr,
  input         W0_en,
                W0_clk,
  input  [64:0] W0_data,
  input  [5:0]  W1_addr,
  input         W1_en,
                W1_clk,
  input  [64:0] W1_data
);

  reg [64:0] Memory[0:63];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
    if (W1_en & 1'h1)
      Memory[W1_addr] <= W1_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 65'bx;
  assign R1_data = R1_en ? Memory[R1_addr] : 65'bx;
  assign R2_data = R2_en ? Memory[R2_addr] : 65'bx;
endmodule

module FullyPortedRF(
  input         clock,
  input  [5:0]  io_arb_read_reqs_0_bits,
                io_arb_read_reqs_1_bits,
                io_arb_read_reqs_2_bits,
  output [64:0] io_rrd_read_resps_0,
                io_rrd_read_resps_1,
                io_rrd_read_resps_2,
  input         io_write_ports_0_valid,
  input  [6:0]  io_write_ports_0_bits_addr,
  input  [64:0] io_write_ports_0_bits_data,
  input         io_write_ports_1_valid,
  input  [6:0]  io_write_ports_1_bits_addr,
  input  [64:0] io_write_ports_1_bits_data
);

  reg [5:0] io_rrd_read_resps_0_REG;
  reg [5:0] io_rrd_read_resps_1_REG;
  reg [5:0] io_rrd_read_resps_2_REG;
  always @(posedge clock) begin
    io_rrd_read_resps_0_REG <= io_arb_read_reqs_0_bits;
    io_rrd_read_resps_1_REG <= io_arb_read_reqs_1_bits;
    io_rrd_read_resps_2_REG <= io_arb_read_reqs_2_bits;
  end // always @(posedge)
  regfile_64x65 regfile_ext (
    .R0_addr (io_rrd_read_resps_2_REG),
    .R0_en   (1'h1),
    .R0_clk  (clock),
    .R0_data (io_rrd_read_resps_2),
    .R1_addr (io_rrd_read_resps_1_REG),
    .R1_en   (1'h1),
    .R1_clk  (clock),
    .R1_data (io_rrd_read_resps_1),
    .R2_addr (io_rrd_read_resps_0_REG),
    .R2_en   (1'h1),
    .R2_clk  (clock),
    .R2_data (io_rrd_read_resps_0),
    .W0_addr (io_write_ports_1_bits_addr[5:0]),
    .W0_en   (io_write_ports_1_valid),
    .W0_clk  (clock),
    .W0_data (io_write_ports_1_bits_data),
    .W1_addr (io_write_ports_0_bits_addr[5:0]),
    .W1_en   (io_write_ports_0_valid),
    .W1_clk  (clock),
    .W1_data (io_write_ports_0_bits_data)
  );
endmodule

module PartiallyPortedRF(
  input         clock,
                io_arb_read_reqs_0_valid,
  input  [5:0]  io_arb_read_reqs_0_bits,
  input         io_arb_read_reqs_1_valid,
  input  [5:0]  io_arb_read_reqs_1_bits,
  output        io_arb_read_reqs_2_ready,
  input         io_arb_read_reqs_2_valid,
  input  [5:0]  io_arb_read_reqs_2_bits,
  output [64:0] io_rrd_read_resps_0,
                io_rrd_read_resps_1,
                io_rrd_read_resps_2,
  input         io_write_ports_0_valid,
  input  [6:0]  io_write_ports_0_bits_addr,
  input  [64:0] io_write_ports_0_bits_data,
  input         io_write_ports_1_valid,
  input  [6:0]  io_write_ports_1_bits_addr,
  input  [64:0] io_write_ports_1_bits_data
);

  wire [64:0] _rf_io_rrd_read_resps_0;
  wire [64:0] _rf_io_rrd_read_resps_1;
  wire [64:0] _rf_io_rrd_read_resps_2;
  wire        use_port_3 = ~io_arb_read_reqs_0_valid & io_arb_read_reqs_1_valid;
  wire        _GEN = use_port_3 | io_arb_read_reqs_0_valid;
  wire        use_port_4 = ~use_port_3 & io_arb_read_reqs_1_valid;
  wire        use_port_5 = ~(use_port_4 | use_port_3) & io_arb_read_reqs_1_valid;
  wire        use_port_6 = ~_GEN & io_arb_read_reqs_2_valid;
  wire        use_port_7 = ~use_port_6 & ~use_port_4 & io_arb_read_reqs_2_valid;
  wire        use_port_8 =
    ~(use_port_7 | use_port_6) & ~use_port_5 & io_arb_read_reqs_2_valid;
  reg  [2:0]  rrd_data_sels_0;
  reg  [2:0]  rrd_data_sels_1;
  reg  [2:0]  rrd_data_sels_2;
  always @(posedge clock) begin
    rrd_data_sels_0 <= 3'h1;
    rrd_data_sels_1 <= use_port_5 ? 3'h4 : use_port_4 ? 3'h2 : 3'h1;
    rrd_data_sels_2 <= use_port_8 ? 3'h4 : use_port_7 ? 3'h2 : 3'h1;
  end // always @(posedge)
  FullyPortedRF rf (
    .clock                      (clock),
    .io_arb_read_reqs_0_bits
      ((io_arb_read_reqs_0_valid ? io_arb_read_reqs_0_bits : 6'h0)
       | (io_arb_read_reqs_0_valid | ~use_port_3 ? 6'h0 : io_arb_read_reqs_1_bits)
       | (_GEN | ~use_port_6 ? 6'h0 : io_arb_read_reqs_2_bits)),
    .io_arb_read_reqs_1_bits
      ((use_port_4 ? io_arb_read_reqs_1_bits : 6'h0)
       | (use_port_4 | ~use_port_7 ? 6'h0 : io_arb_read_reqs_2_bits)),
    .io_arb_read_reqs_2_bits
      ((use_port_5 ? io_arb_read_reqs_1_bits : 6'h0)
       | (use_port_5 | ~use_port_8 ? 6'h0 : io_arb_read_reqs_2_bits)),
    .io_rrd_read_resps_0        (_rf_io_rrd_read_resps_0),
    .io_rrd_read_resps_1        (_rf_io_rrd_read_resps_1),
    .io_rrd_read_resps_2        (_rf_io_rrd_read_resps_2),
    .io_write_ports_0_valid     (io_write_ports_0_valid),
    .io_write_ports_0_bits_addr (io_write_ports_0_bits_addr),
    .io_write_ports_0_bits_data (io_write_ports_0_bits_data),
    .io_write_ports_1_valid     (io_write_ports_1_valid),
    .io_write_ports_1_bits_addr (io_write_ports_1_bits_addr),
    .io_write_ports_1_bits_data (io_write_ports_1_bits_data)
  );
  assign io_arb_read_reqs_2_ready =
    {1'h0, io_arb_read_reqs_0_valid} + {1'h0, io_arb_read_reqs_1_valid} != 2'h3;
  assign io_rrd_read_resps_0 =
    (rrd_data_sels_0[0] ? _rf_io_rrd_read_resps_0 : 65'h0)
    | (rrd_data_sels_0[1] ? _rf_io_rrd_read_resps_1 : 65'h0)
    | (rrd_data_sels_0[2] ? _rf_io_rrd_read_resps_2 : 65'h0);
  assign io_rrd_read_resps_1 =
    (rrd_data_sels_1[0] ? _rf_io_rrd_read_resps_0 : 65'h0)
    | (rrd_data_sels_1[1] ? _rf_io_rrd_read_resps_1 : 65'h0)
    | (rrd_data_sels_1[2] ? _rf_io_rrd_read_resps_2 : 65'h0);
  assign io_rrd_read_resps_2 =
    (rrd_data_sels_2[0] ? _rf_io_rrd_read_resps_0 : 65'h0)
    | (rrd_data_sels_2[1] ? _rf_io_rrd_read_resps_1 : 65'h0)
    | (rrd_data_sels_2[2] ? _rf_io_rrd_read_resps_2 : 65'h0);
endmodule

