module BranchMaskGenerationLogic(
  input         clock,
                reset,
                io_is_branch_0,
                io_is_branch_1,
                io_will_fire_0,
                io_will_fire_1,
  output [3:0]  io_br_tag_0,
                io_br_tag_1,
  output [11:0] io_br_mask_0,
                io_br_mask_1,
  output        io_is_full_0,
                io_is_full_1,
  input  [11:0] io_brupdate_b1_resolve_mask,
                io_brupdate_b2_uop_br_mask,
  input         io_brupdate_b2_mispredict,
                io_flush_pipeline
);

  reg  [11:0] branch_mask;
  wire [11:0] tag_masks_0 =
    branch_mask[0]
      ? (branch_mask[1]
           ? (branch_mask[2]
                ? (branch_mask[3]
                     ? (branch_mask[4]
                          ? (branch_mask[5]
                               ? (branch_mask[6]
                                    ? (branch_mask[7]
                                         ? (branch_mask[8]
                                              ? (branch_mask[9]
                                                   ? (branch_mask[10]
                                                        ? {~(branch_mask[11]), 11'h0}
                                                        : 12'h400)
                                                   : 12'h200)
                                              : 12'h100)
                                         : 12'h80)
                                    : 12'h40)
                               : 12'h20)
                          : 12'h10)
                     : 12'h8)
                : 12'h4)
           : 12'h2)
      : 12'h1;
  wire [11:0] _GEN = {12{io_is_branch_0}} & tag_masks_0 | branch_mask;
  wire [11:0] _GEN_0 = {12{io_will_fire_0}} & tag_masks_0 | branch_mask;
  always @(posedge clock) begin
    if (reset)
      branch_mask <= 12'h0;
    else
      branch_mask <=
        io_flush_pipeline
          ? 12'h0
          : ({12{io_will_fire_1}}
             & (_GEN[0]
                  ? (_GEN[1]
                       ? (_GEN[2]
                            ? (_GEN[3]
                                 ? (_GEN[4]
                                      ? (_GEN[5]
                                           ? (_GEN[6]
                                                ? (_GEN[7]
                                                     ? (_GEN[8]
                                                          ? (_GEN[9]
                                                               ? (_GEN[10]
                                                                    ? {~(_GEN[11]), 11'h0}
                                                                    : 12'h400)
                                                               : 12'h200)
                                                          : 12'h100)
                                                     : 12'h80)
                                                : 12'h40)
                                           : 12'h20)
                                      : 12'h10)
                                 : 12'h8)
                            : 12'h4)
                       : 12'h2)
                  : 12'h1) | _GEN_0) & ~io_brupdate_b1_resolve_mask
            & (io_brupdate_b2_mispredict ? io_brupdate_b2_uop_br_mask : 12'hFFF);
  end // always @(posedge)
  assign io_br_tag_0 =
    branch_mask[0]
      ? (branch_mask[1]
           ? (branch_mask[2]
                ? (branch_mask[3]
                     ? (branch_mask[4]
                          ? (branch_mask[5]
                               ? (branch_mask[6]
                                    ? (branch_mask[7]
                                         ? (branch_mask[8]
                                              ? (branch_mask[9]
                                                   ? (branch_mask[10]
                                                        ? (branch_mask[11] ? 4'h0 : 4'hB)
                                                        : 4'hA)
                                                   : 4'h9)
                                              : 4'h8)
                                         : 4'h7)
                                    : 4'h6)
                               : 4'h5)
                          : 4'h4)
                     : 4'h3)
                : 4'h2)
           : 4'h1)
      : 4'h0;
  assign io_br_tag_1 =
    _GEN[0]
      ? (_GEN[1]
           ? (_GEN[2]
                ? (_GEN[3]
                     ? (_GEN[4]
                          ? (_GEN[5]
                               ? (_GEN[6]
                                    ? (_GEN[7]
                                         ? (_GEN[8]
                                              ? (_GEN[9]
                                                   ? (_GEN[10]
                                                        ? (_GEN[11] ? 4'h0 : 4'hB)
                                                        : 4'hA)
                                                   : 4'h9)
                                              : 4'h8)
                                         : 4'h7)
                                    : 4'h6)
                               : 4'h5)
                          : 4'h4)
                     : 4'h3)
                : 4'h2)
           : 4'h1)
      : 4'h0;
  assign io_br_mask_0 = branch_mask & ~io_brupdate_b1_resolve_mask;
  assign io_br_mask_1 = _GEN_0 & ~io_brupdate_b1_resolve_mask;
  assign io_is_full_0 = (&branch_mask) & io_is_branch_0;
  assign io_is_full_1 = (&_GEN) & io_is_branch_1;
endmodule

