// VCS coverage exclude_file
module regfile_32x1(
  input  [4:0] R0_addr,
  input        R0_en,
               R0_clk,
  output       R0_data,
  input  [4:0] R1_addr,
  input        R1_en,
               R1_clk,
  output       R1_data,
  input  [4:0] W0_addr,
  input        W0_en,
               W0_clk,
               W0_data
);

  reg Memory[0:31];
  always @(posedge W0_clk) begin
    if (W0_en & 1'h1)
      Memory[W0_addr] <= W0_data;
  end // always @(posedge)
  assign R0_data = R0_en ? Memory[R0_addr] : 1'bx;
  assign R1_data = R1_en ? Memory[R1_addr] : 1'bx;
endmodule

