module Arbiter2_Wakeup(
  input        io_in_0_valid,
  input  [6:0] io_in_0_bits_uop_pdst,
  input        io_in_0_bits_bypassable,
               io_in_0_bits_rebusy,
  output       io_in_1_ready,
  input        io_in_1_valid,
  input  [6:0] io_in_1_bits_uop_pdst,
  output       io_out_valid,
  output [6:0] io_out_bits_uop_pdst,
  output       io_out_bits_bypassable,
               io_out_bits_rebusy
);

  assign io_in_1_ready = ~io_in_0_valid;
  assign io_out_valid = io_in_0_valid | io_in_1_valid;
  assign io_out_bits_uop_pdst =
    io_in_0_valid ? io_in_0_bits_uop_pdst : io_in_1_bits_uop_pdst;
  assign io_out_bits_bypassable = ~io_in_0_valid | io_in_0_bits_bypassable;
  assign io_out_bits_rebusy = io_in_0_valid & io_in_0_bits_rebusy;
endmodule

module ForwardingAgeLogic(
  input         clock,
  input  [15:0] io_matches,
  input  [3:0]  io_youngest,
  output        io_found,
  output [3:0]  io_found_idx
);

  reg         found_match;
  reg  [3:0]  found_idx;
  wire [15:0] _matches_T_1 =
    io_matches
    & {1'h0,
       &io_youngest,
       io_youngest > 4'hD,
       io_youngest > 4'hC,
       io_youngest > 4'hB,
       io_youngest > 4'hA,
       io_youngest > 4'h9,
       io_youngest > 4'h8,
       io_youngest[3],
       io_youngest > 4'h6,
       io_youngest > 4'h5,
       io_youngest > 4'h4,
       |(io_youngest[3:2]),
       io_youngest > 4'h2,
       |(io_youngest[3:1]),
       |io_youngest};
  always @(posedge clock) begin
    found_match <=
      _matches_T_1[15] | _matches_T_1[14] | _matches_T_1[13] | _matches_T_1[12]
      | _matches_T_1[11] | _matches_T_1[10] | _matches_T_1[9] | _matches_T_1[8]
      | _matches_T_1[7] | _matches_T_1[6] | _matches_T_1[5] | _matches_T_1[4]
      | _matches_T_1[3] | _matches_T_1[2] | _matches_T_1[1] | _matches_T_1[0]
      | io_matches[15] | io_matches[14] | io_matches[13] | io_matches[12] | io_matches[11]
      | io_matches[10] | io_matches[9] | io_matches[8] | io_matches[7] | io_matches[6]
      | io_matches[5] | io_matches[4] | io_matches[3] | io_matches[2] | io_matches[1]
      | io_matches[0];
    found_idx <=
      _matches_T_1[15]
        ? 4'hF
        : _matches_T_1[14]
            ? 4'hE
            : _matches_T_1[13]
                ? 4'hD
                : _matches_T_1[12]
                    ? 4'hC
                    : _matches_T_1[11]
                        ? 4'hB
                        : _matches_T_1[10]
                            ? 4'hA
                            : _matches_T_1[9]
                                ? 4'h9
                                : _matches_T_1[8]
                                    ? 4'h8
                                    : _matches_T_1[7]
                                        ? 4'h7
                                        : _matches_T_1[6]
                                            ? 4'h6
                                            : _matches_T_1[5]
                                                ? 4'h5
                                                : _matches_T_1[4]
                                                    ? 4'h4
                                                    : _matches_T_1[3]
                                                        ? 4'h3
                                                        : _matches_T_1[2]
                                                            ? 4'h2
                                                            : _matches_T_1[1]
                                                                ? 4'h1
                                                                : _matches_T_1[0]
                                                                    ? 4'h0
                                                                    : io_matches[15]
                                                                        ? 4'hF
                                                                        : io_matches[14]
                                                                            ? 4'hE
                                                                            : io_matches[13]
                                                                                ? 4'hD
                                                                                : io_matches[12]
                                                                                    ? 4'hC
                                                                                    : io_matches[11]
                                                                                        ? 4'hB
                                                                                        : io_matches[10]
                                                                                            ? 4'hA
                                                                                            : io_matches[9]
                                                                                                ? 4'h9
                                                                                                : io_matches[8]
                                                                                                    ? 4'h8
                                                                                                    : io_matches[7]
                                                                                                        ? 4'h7
                                                                                                        : io_matches[6]
                                                                                                            ? 4'h6
                                                                                                            : io_matches[5]
                                                                                                                ? 4'h5
                                                                                                                : io_matches[4]
                                                                                                                    ? 4'h4
                                                                                                                    : io_matches[3]
                                                                                                                        ? 4'h3
                                                                                                                        : io_matches[2]
                                                                                                                            ? 4'h2
                                                                                                                            : {3'h0,
                                                                                                                               io_matches[1]};
  end // always @(posedge)
  assign io_found = found_match;
  assign io_found_idx = found_idx;
endmodule

