  input  [3:0]  auto_out_r_bits_id,
  input  [63:0] auto_out_r_bits_data,
  input  [1:0]  auto_out_r_bits_resp,
  input         auto_out_r_bits_echo_real_last,
                auto_out_r_bits_last
);

  wire             w_idle;
  wire             in_aw_ready;
  wire             _in_w_deq_q_io_deq_valid;
  wire             _deq_q_1_io_deq_valid;
  wire [31:0]      _deq_q_1_io_deq_bits_addr;
  wire [7:0]       _deq_q_1_io_deq_bits_len;
  wire [2:0]       _deq_q_1_io_deq_bits_size;
  wire [1:0]       _deq_q_1_io_deq_bits_burst;
  wire             _deq_q_io_deq_valid;
  wire [31:0]      _deq_q_io_deq_bits_addr;
  wire [7:0]       _deq_q_io_deq_bits_len;
  wire [2:0]       _deq_q_io_deq_bits_size;
  wire [1:0]       _deq_q_io_deq_bits_burst;
  reg              busy;
  reg  [31:0]      r_addr;
  reg  [7:0]       r_len;
  wire [7:0]       len = busy ? r_len : _deq_q_io_deq_bits_len;
  wire [31:0]      addr = busy ? r_addr : _deq_q_io_deq_bits_addr;
  wire [31:0]      _out_bits_addr_T = ~addr;
  wire [9:0]       _out_bits_addr_T_1 = 10'h7 << _deq_q_io_deq_bits_size;
  reg              busy_1;
  reg  [31:0]      r_addr_1;
  reg  [7:0]       r_len_1;
  wire [7:0]       len_1 = busy_1 ? r_len_1 : _deq_q_1_io_deq_bits_len;
  wire [31:0]      addr_1 = busy_1 ? r_addr_1 : _deq_q_1_io_deq_bits_addr;
  wire [31:0]      _out_bits_addr_T_6 = ~addr_1;
  wire [9:0]       _out_bits_addr_T_7 = 10'h7 << _deq_q_1_io_deq_bits_size;
  reg              wbeats_latched;
  wire             _in_aw_ready_T = w_idle | wbeats_latched;
  wire             nodeOut_aw_valid = _deq_q_1_io_deq_valid & _in_aw_ready_T;
  assign in_aw_ready = auto_out_aw_ready & _in_aw_ready_T;
  wire             wbeats_valid = _deq_q_1_io_deq_valid & ~wbeats_latched;
  reg  [8:0]       w_counter;
  assign w_idle = w_counter == 9'h0;
  wire [8:0]       w_todo = w_idle ? {8'h0, wbeats_valid} : w_counter;
  wire             nodeOut_w_valid = _in_w_deq_q_io_deq_valid & (~w_idle | wbeats_valid);
  wire             nodeOut_b_ready = auto_in_b_ready | ~auto_out_b_bits_echo_real_last;
  reg  [1:0]       error_0;
  reg  [1:0]       error_1;
  reg  [1:0]       error_2;
  reg  [1:0]       error_3;
  reg  [1:0]       error_4;
  reg  [1:0]       error_5;
  reg  [1:0]       error_6;
  reg  [1:0]       error_7;
  reg  [1:0]       error_8;
  reg  [1:0]       error_9;
  reg  [1:0]       error_10;
  reg  [1:0]       error_11;
  reg  [1:0]       error_12;
  reg  [1:0]       error_13;
  reg  [1:0]       error_14;
  reg  [1:0]       error_15;
  wire [15:0][1:0] _GEN =
    {{error_15},
     {error_14},
     {error_13},
     {error_12},
     {error_11},
     {error_10},
     {error_9},
     {error_8},
     {error_7},
     {error_6},
     {error_5},
     {error_4},
     {error_3},
     {error_2},
     {error_1},
     {error_0}};
  wire [15:0]      _GEN_0 = 16'h1 << auto_out_b_bits_id;
  wire             _GEN_1 = nodeOut_b_ready & auto_out_b_valid;
  wire [31:0]      _inc_addr_T_1 = addr + {16'h0, 16'h1 << _deq_q_io_deq_bits_size};
  wire [22:0]      _wrapMask_T_1 =
    {7'h0, _deq_q_io_deq_bits_len, 8'hFF} << _deq_q_io_deq_bits_size;
  wire [31:0]      _mux_addr_T_1 = ~_deq_q_io_deq_bits_addr;
  wire [31:0]      _inc_addr_T_3 = addr_1 + {16'h0, 16'h1 << _deq_q_1_io_deq_bits_size};
  wire [22:0]      _wrapMask_T_3 =
    {7'h0, _deq_q_1_io_deq_bits_len, 8'hFF} << _deq_q_1_io_deq_bits_size;
  wire [31:0]      _mux_addr_T_6 = ~_deq_q_1_io_deq_bits_addr;
  wire             _GEN_2 = auto_out_ar_ready & _deq_q_io_deq_valid;
  wire             _GEN_3 = in_aw_ready & _deq_q_1_io_deq_valid;
  always @(posedge clock) begin
    if (reset) begin
      busy <= 1'h0;
      busy_1 <= 1'h0;
      wbeats_latched <= 1'h0;
      w_counter <= 9'h0;
      error_0 <= 2'h0;
      error_1 <= 2'h0;
      error_2 <= 2'h0;
      error_3 <= 2'h0;
      error_4 <= 2'h0;
      error_5 <= 2'h0;
      error_6 <= 2'h0;
      error_7 <= 2'h0;
      error_8 <= 2'h0;
      error_9 <= 2'h0;
      error_10 <= 2'h0;
      error_11 <= 2'h0;
      error_12 <= 2'h0;
      error_13 <= 2'h0;
      error_14 <= 2'h0;
      error_15 <= 2'h0;
    end
    else begin
      if (_GEN_2)
        busy <= |len;
      if (_GEN_3)
        busy_1 <= |len_1;
      wbeats_latched <=
        ~(auto_out_aw_ready & nodeOut_aw_valid)
        & (wbeats_valid & w_idle | wbeats_latched);
      w_counter <= w_todo - {8'h0, auto_out_w_ready & nodeOut_w_valid};
      if (_GEN_0[0] & _GEN_1)
        error_0 <= auto_out_b_bits_echo_real_last ? 2'h0 : error_0 | auto_out_b_bits_resp;
      if (_GEN_0[1] & _GEN_1)
        error_1 <= auto_out_b_bits_echo_real_last ? 2'h0 : error_1 | auto_out_b_bits_resp;
      if (_GEN_0[2] & _GEN_1)
        error_2 <= auto_out_b_bits_echo_real_last ? 2'h0 : error_2 | auto_out_b_bits_resp;
      if (_GEN_0[3] & _GEN_1)
        error_3 <= auto_out_b_bits_echo_real_last ? 2'h0 : error_3 | auto_out_b_bits_resp;
      if (_GEN_0[4] & _GEN_1)
        error_4 <= auto_out_b_bits_echo_real_last ? 2'h0 : error_4 | auto_out_b_bits_resp;
      if (_GEN_0[5] & _GEN_1)
        error_5 <= auto_out_b_bits_echo_real_last ? 2'h0 : error_5 | auto_out_b_bits_resp;
